NAMED_PICKUP_SOURCE_LOCATION_NAMES: frozenset[str] = frozenset((
    "Far Fields - Pale Rosary Necklace",
    "Hunter's March - Rosary Necklace",
))

MINOR_CACHE_LOCATION_NAMES: tuple[str, ...] = tuple(
    location_name
    for source_name, *_identity in MINOR_CACHE_SOURCE
    if (
        location_name := location_first_name(source_name)
    ) not in NAMED_PICKUP_SOURCE_LOCATION_NAMES
)

RETIRED_MINOR_CACHE_LOCATION_NAMES: frozenset[str] = frozenset((
    "Shellwood - Shell Shard Cache #7",
    "Shellwood - Shell Shard Cache #8",
    "Hunter's March - Rosary Chest",
    "Far Fields - Rosary Chest #2",
))

ACTIVE_MINOR_CACHE_LOCATION_NAMES: tuple[str, ...] = tuple(
    location_name
    for location_name in MINOR_CACHE_LOCATION_NAMES
    if location_name not in RETIRED_MINOR_CACHE_LOCATION_NAMES
)

MINOR_CACHE_REWARD_BY_LOCATION: dict[str, str] = {
    location_first_name(location_name): reward_name
    for location_name, reward_name, *_identity in MINOR_CACHE_SOURCE
    if location_first_name(location_name) in ACTIVE_MINOR_CACHE_LOCATION_NAMES
}

MINOR_CACHE_FAMILY_BY_LOCATION: dict[str, str] = {
    location_name: (
        "shell_shard_cache"
        if "Shell Shard" in location_name
        else "rosary_cache"
    )
    for location_name in MINOR_CACHE_REWARD_BY_LOCATION
}

MINOR_CACHE_REWARD_COUNTS: dict[str, int] = dict(
    Counter(MINOR_CACHE_REWARD_BY_LOCATION.values())
)

MINOR_CACHE_DISPLAY_AREA_BY_LOCATION: dict[str, str] = {
    location_first_name(location_name): display_area
    for (
        location_name,
        _reward_name,
        _scene_name,
        _object_name,
        _hook_kind,
        _x,
        _y,
        _scene_width,
        _scene_height,
        _map_region,
        display_area,
    ) in MINOR_CACHE_SOURCE
    if location_first_name(location_name) in ACTIVE_MINOR_CACHE_LOCATION_NAMES
}
